import {
	Button,
	Container,
	Text,
	Title,
	Modal,
	TextInput,
	Group,
	Card,
	ActionIcon,
	Code,
  } from '@mantine/core';
  import { useState, useRef, useEffect } from 'react';
  import { MoonStars, Sun, Trash } from 'tabler-icons-react';
  
  import {
	MantineProvider,
	ColorSchemeProvider,
	ColorScheme,
  } from '@mantine/core';
  import { useColorScheme } from '@mantine/hooks';
  import { useHotkeys, useLocalStorage } from '@mantine/hooks';
  
  export default function App() {
	const [tasks, setTasks] = useState([]);
	const [opened, setOpened] = useState(false);
	// Nouveau state pour gérer l'état d'erreur si aucun titre n'est saisi
	const [titleError, setTitleError] = useState('');
	// Nouveau state pour empêcher les clics répétitifs lors de la création d'une tâche
	const [isCreating, setIsCreating] = useState(false);
  
	const preferredColorScheme = useColorScheme();
	const [colorScheme, setColorScheme] = useLocalStorage({
	  key: 'mantine-color-scheme',
	  defaultValue: 'light',
	  getInitialValueInEffect: true,
	});
	const toggleColorScheme = value =>
	  setColorScheme(value || (colorScheme === 'dark' ? 'light' : 'dark'));
  
	useHotkeys([['mod+J', () => toggleColorScheme()]]);
  
	const taskTitle = useRef('');
	const taskSummary = useRef('');
  
	function createTask() {
	  // Vérification que le titre n'est pas vide (après suppression des espaces)
	  if (!taskTitle.current.value.trim()) {
		// Si le titre est vide, on affiche un message d'erreur en rouge et on n'effectue pas la création
		setTitleError('Title is required');
		return;
	  } else {
		// Sinon, on efface le message d'erreur
		setTitleError('');
	  }
	  
	  // Si une tâche est déjà en cours de création, on ne traite pas le clic
	  if (isCreating) {
		return;
	  }
  
	  // Désactiver temporairement la création pour empêcher le spam
	  setIsCreating(true);
  
	  const newTask = {
		title: taskTitle.current.value,
		summary: taskSummary.current.value,
	  };
  
	  // Mettre à jour l'état et sauvegarder dans le localStorage
	  setTasks([...tasks, newTask]);
	  saveTasks([...tasks, newTask]);
  
	  // Réactiver le bouton de création après la création
	  setIsCreating(false);
	}
  
	function deleteTask(index) {
	  var clonedTasks = [...tasks];
	  clonedTasks.splice(index, 1);
	  setTasks(clonedTasks);
	  saveTasks([...clonedTasks]);
	}
  
	function loadTasks() {
	  let loadedTasks = localStorage.getItem('tasks');
	  let tasks = JSON.parse(loadedTasks);
	  if (tasks) {
		setTasks(tasks);
	  }
	}
  
	function saveTasks(tasks) {
	  localStorage.setItem('tasks', JSON.stringify(tasks));
	}
  
	useEffect(() => {
	  loadTasks();
	}, []);
  
	return (
	  <ColorSchemeProvider colorScheme={colorScheme} toggleColorScheme={toggleColorScheme}>
		<MantineProvider theme={{ colorScheme, defaultRadius: 'md' }} withGlobalStyles withNormalizeCSS>
		  <div className='App'>
			<Modal
			  data-cy="task-modal" // Identifie la modale d'ajout
			  opened={opened}
			  size={'md'}
			  title={'New Task'}
			  withCloseButton={false}
			  onClose={() => {
				setOpened(false);
				// Réinitialiser l'erreur si la modale est fermée
				setTitleError('');
			  }}
			  centered
			>
			  <TextInput
				data-cy="task-title-input" // Champ pour le titre
				mt={'md'}
				ref={taskTitle}
				placeholder={'Task Title'}
				required
				label={'Title'}
			  />
			  {/* Affichage du message d'erreur si le titre est vide */}
			  {titleError && (
				<Text color="red" size="sm" mt="xs" data-cy="title-error">
				  {titleError}
				</Text>
			  )}
			  <TextInput
				data-cy="task-summary-input" // Champ pour le résumé
				ref={taskSummary}
				mt={'md'}
				placeholder={'Task Summary'}
				label={'Summary'}
			  />
			  <Group mt={'md'} position={'apart'}>
				<Button
				  data-cy="cancel-button" // Bouton Cancel
				  onClick={() => {
					setOpened(false);
					setTitleError(''); // Effacer l'erreur en cas d'annulation
				  }}
				  variant={'subtle'}
				>
				  Cancel
				</Button>
				<Button
				  data-cy="create-task-button" // Bouton Create Task
				  // Désactiver le bouton pendant la création pour éviter les clics multiples
				  disabled={isCreating}
				  onClick={() => {
					createTask();
					// Fermer la modale uniquement si le titre est valide
					if (taskTitle.current.value.trim()) {
					  setOpened(false);
					}
				  }}
				>
				  Create Task
				</Button>
			  </Group>
			</Modal>
			<Container size={550} my={40}>
			  <Group position={'apart'}>
				<Title
				  data-cy="page-title" // Titre de la page
				  sx={theme => ({
					fontFamily: `Greycliff CF, ${theme.fontFamily}`,
					fontWeight: 900,
				  })}
				>
				  My Tasks
				</Title>
				<ActionIcon
				  data-cy="theme-toggle" // Bouton de basculement du thème
				  color={'blue'}
				  onClick={() => toggleColorScheme()}
				  size='lg'
				>
				  {colorScheme === 'dark' ? <Sun size={16} /> : <MoonStars size={16} />}
				</ActionIcon>
			  </Group>
			  {tasks.length > 0 ? (
				tasks.map((task, index) => {
				  if (task.title) {
					return (
					  <Card data-cy="task-card" withBorder key={index} mt={'sm'}>
						<Group position={'apart'}>
						  <Text weight={'bold'}>{task.title}</Text>
						  <ActionIcon
							data-cy="delete-task-button" // Bouton de suppression de la tâche
							onClick={() => {
							  deleteTask(index);
							}}
							color={'red'}
							variant={'transparent'}
						  >
							<Trash />
						  </ActionIcon>
						</Group>
						<Text color={'dimmed'} size={'md'} mt={'sm'}>
						  {task.summary ? task.summary : 'No summary was provided for this task'}
						</Text>
					  </Card>
					);
				  }
				})
			  ) : (
				<Text data-cy="empty-message" size={'lg'} mt={'md'} color={'dimmed'}>
				  You have no tasks
				</Text>
			  )}
			  <Button
				data-cy="new-task-button" // Bouton pour ouvrir la modale d'ajout
				onClick={() => {
				  setOpened(true);
				}}
				fullWidth
				mt={'md'}
			  >
				New Task
			  </Button>
			</Container>
		  </div>
		</MantineProvider>
	  </ColorSchemeProvider>
	);
  }
